@@ -0,0 +1,15 @@
+import { mkdir, writeFile } from 'node:fs/promises';
+import path from 'node:path';
+
+const UPLOAD_ROOT = process.env.UPLOAD_ROOT ?? '/var/lib/uploads';
+
+/**
+ * Persist one upload. `name` is the value the client sent in the multipart
+ * filename field, so it is untrusted input.
+ */
+export async function storeUpload(name: string, bytes: Buffer): Promise<string> {
+  const target = path.join(UPLOAD_ROOT, name);
+  await mkdir(path.dirname(target), { recursive: true });
+  await writeFile(target, bytes);
+  return target;
+}
